<script setup>
import {ref} from 'vue';import {api} from '../auth/api.js';import {refreshUnread} from './notifications.js';import {useCollection} from '../home/useCollection.js';import {LegacyState,LegacyPager,date} from '../../lib/legacy.js';import BusinessPage from '../../components/BusinessPage.vue';
const unread=ref(false),state=useCollection('/users/me/notifications',null,()=>({unread:unread.value}));
async function mark(item){await state.run(async()=>{await api('/users/me/notifications/'+item.id+'/read',{method:'PATCH'});await Promise.all([state.load(state.page),refreshUnread()])})}
async function all(){await state.run(async()=>{await api('/users/me/notifications/read-all',{method:'POST'});await Promise.all([state.load(state.page),refreshUnread()])})}
</script><template><BusinessPage title="Trung tâm thông báo"><label><input type="checkbox" v-model="unread"/> Chỉ chưa đọc</label><button :disabled="state.busy" @click="all">Đánh dấu tất cả đã đọc</button><LegacyState :state="state"/><p>{{state.totalElements}} kết quả theo bộ lọc</p><p v-if="!state.busy&&!state.items.length">Chưa có thông báo phù hợp.</p><section v-for="item in state.items" :key="item.id"><h2>{{item.title}}</h2><p class="whitespace-pre-wrap">{{item.body}}</p><p>{{date(item.createdAt)}} · {{item.readAt?'Đã đọc':'Chưa đọc'}}</p><button v-if="!item.readAt" :disabled="state.busy" @click="mark(item)">Đánh dấu đã đọc</button><RouterLink v-if="item.propertyId" :to="'/listing/'+item.propertyId" class="underline">Xem tin</RouterLink><RouterLink v-if="item.reportId" to="/account/reports" class="ml-3 underline">Xem báo cáo của tôi</RouterLink></section><LegacyPager :state="state"/></BusinessPage></template>
